+#[test]
+fn swarf_opening_states_rotaries_before_the_fanuc_tilted_feed() {
+    let stock = (
+        StockShape::Cylinder { diameter: 24.4, height: 48.0 },
+        Location { pos: Point3::new(-24.0, 0.0, 0.0), rot: quat_from_axis_angle(1, std::f64::consts::FRAC_PI_2) },
+    );
